begin;
select set_config('ey.test_user',gen_random_uuid()::text,true),set_config('ey.other_user',gen_random_uuid()::text,true),set_config('ey.test_teacher',gen_random_uuid()::text,true);
insert into auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select current_setting(k)::uuid,'authenticated','authenticated',current_setting(k)||'@example.invalid',now(),'{}','{"full_name":"Rollback-only QA","class_id":1}',now(),now()from unnest(array['ey.test_user','ey.other_user','ey.test_teacher'])k;
update public.student_profiles set class_id=1,home_class_id=1,initial_class_id=1 where id in(current_setting('ey.test_user')::uuid,current_setting('ey.other_user')::uuid,current_setting('ey.test_teacher')::uuid);
insert into public.teacher_profiles(id,full_name,class_id,is_active,starts_at,expires_at,created_by)values(current_setting('ey.test_teacher')::uuid,'Rollback QA Teacher',1,true,now()-interval '1 day',now()+interval '30 days',current_setting('ey.test_teacher')::uuid);
set local role service_role;
do $$declare u uuid:=current_setting('ey.test_user')::uuid;other_u uuid:=current_setting('ey.other_user')::uuid;t uuid:=current_setting('ey.test_teacher')::uuid;r jsonb;r2 jsonb;q bigint;v jsonb;aid uuid;attempt bigint;before_count int;after_count int;begin
 r:=public.ey_start(u,1,'DAILY');assert jsonb_array_length(r->'questions')=5,'daily count';
 r2:=public.ey_start(u,1,'DAILY');assert r->>'id'=r2->>'id','daily idempotency';
 q:=(r->'questions'->0->>'id')::bigint;
 begin perform public.ey_answer(other_u,(r->>'id')::uuid,q,'A');raise exception 'ownership check did not reject';exception when insufficient_privilege then null;end;
 begin perform public.ey_start(u,2,'DAILY');raise exception 'class isolation did not reject';exception when insufficient_privilege then null;end;
 begin perform public.ey_answer(u,(r->>'id')::uuid,q,'X');raise exception 'answer validation did not reject';exception when raise_exception then if sqlerrm='answer validation did not reject'then raise;end if;end;
 begin perform public.ey_answer(u,(r->>'id')::uuid,-1,'A');raise exception 'question binding did not reject';exception when raise_exception then if sqlerrm='question binding did not reject'then raise;end if;end;
 r2:=public.ey_answer(u,(r->>'id')::uuid,q,'A');r2:=public.ey_answer(u,(r->>'id')::uuid,q,'B');assert r2->'answers'->>q::text='A','first answer lock';
 for v in select * from jsonb_array_elements(r->'questions')loop r2:=public.ey_answer(u,(r->>'id')::uuid,(v->>'id')::bigint,v->>'correct_option');end loop;
 assert r2->>'completed_at'is not null,'completion';
 select sum(sessions)into before_count from public.ey_monthly_progress where student_id=u;
 r2:=public.ey_answer(u,(r->>'id')::uuid,q,'A');select sum(sessions)into after_count from public.ey_monthly_progress where student_id=u;assert before_count=after_count,'no duplicate progress';
 perform public.ey_report(u,q,'Rollback-only QA explanation issue');
 begin perform public.ey_report(other_u,q,'Unauthorized report must be rejected');raise exception 'report ownership did not reject';exception when insufficient_privilege then null;end;
 select c.id into q from public.chapters c join public.subjects s on s.id=c.subject_id where s.class_id=1 and c.is_active and s.is_active and exists(select 1 from public.questions x where x.chapter_id=c.id and x.is_active and x.media_ready and x.question_usage in('PRACTICE','SHARED'))limit 1;
 aid:=public.ey_create_assignment(t,(select subject_id from public.chapters where id=q),q,'Rollback-only chapter quiz',7);
 r:=public.ey_start(u,1,'ASSIGNMENT',null,aid);r2:=public.ey_start(u,1,'ASSIGNMENT',null,aid);assert r->>'id'=r2->>'id','assignment idempotency';
 assert jsonb_array_length(public.ey_assignment_results(t))=1,'teacher own results';assert jsonb_array_length(public.ey_assignment_results(other_u))=0,'other teacher results';
 update public.ey_assignments set is_active=false where id=aid;
 begin perform public.ey_start(other_u,1,'ASSIGNMENT',null,aid);raise exception 'closed assignment did not reject';exception when insufficient_privilege then null;end;
 assert not has_function_privilege('anon','public.ey_snapshot(bigint[])','EXECUTE'),'anonymous answer exposure';
 assert not has_function_privilege('authenticated','public.ey_start(uuid,bigint,text,bigint,uuid)','EXECUTE'),'service-only start';
 assert not has_table_privilege('authenticated','public.ey_sessions','SELECT'),'snapshot table exposure';
 insert into public.quiz_attempts(student_id,subject_id,total_questions,answered_questions,correct_answers,wrong_answers,unanswered_questions,total_marks,obtained_marks,percentage,status,quiz_type,started_at,submitted_at,time_taken_seconds)values(u,(r->'questions'->0->>'subject_id')::bigint,1,1,0,1,0,1,0,0,'COMPLETED','PRACTICE',now(),now(),1)returning id into attempt;
 insert into public.quiz_attempt_answers(attempt_id,question_id,selected_answer,correct_answer,is_correct,marks_obtained)values(attempt,(r->'questions'->0->>'id')::bigint,'A','B',false,0);
 assert jsonb_array_length(public.ey_recommendations(u,1))>=1,'chapter recommendations';
 assert exists(select 1 from public.ey_monthly_progress where student_id=u and source='TEST'),'test aggregate trigger';
 assert (public.ey_growth_metrics()->>'openReports')::int>=1,'aggregate report metrics';
 assert not exists(select 1 from public.free_test_sets where student_id=u),'free allowances untouched';
 raise notice 'PASS: ownership, class isolation, daily/assignment idempotency, locked answers, progress, reporting, teacher scope and grants';
end$$;
reset role;
rollback;
